if (busy) {
  if (!showingLoader) {
    status.textContent = 'recherche des disponibilités'
    loadingIndicator?.start()
    showingLoader = true
  }
} else {
  if (showingLoader) { loadingIndicator?.stop(); showingLoader = false }
  status.textContent = count ? 'Choisissez votre créneau ci-dessous.' : 'Aucun créneau pour ce filtre sur ces 7 jours. Changez de filtre ou consultez les jours suivants.'
}
